            { "obj.shop", new[] { "Монет: {0}. Встань на товар, чтобы купить", "Coins: {0}. Step on an item to buy it", "金币：{0}。站到商品上购买", "Monedas: {0}. Pisa un objeto para comprarlo" } },
            { "obj.shrine", new[] { "Встань на алтарь: реликвия за одно сердце", "Step on the shrine: a relic for one heart", "站上祭坛：以一颗心换遗物", "Pisa el altar: una reliquia por un corazón" } },
            { "obj.fountain", new[] { "Подойди к фонтану, чтобы вылечиться", "Walk to the fountain to heal", "走到泉水边治疗", "Acércate a la fuente para curarte" } },
            { "obj.next", new[] { "Дверь открыта", "The door is open", "门已打开", "La puerta está abierta" } },
            { "pause.coins", new[] { "Монеты: {0}", "Coins: {0}", "金币：{0}", "Monedas: {0}" } },
            { "end.floors", new[] { "Этаж: {0} из {1}", "Floor: {0} of {1}", "楼层：{0}/{1}", "Piso: {0} de {1}" } },
            { "end.floorEndless", new[] { "Этаж: {0}", "Floor: {0}", "楼层：{0}", "Piso: {0}" } },
            { "unlock.chaos", new[] { "режим «Хаос»", "Chaos mode", "混沌模式", "modo Caos" } },
            { "hint.shop", new[] { "Монеты падают с врагов. В лавке их можно потратить на реликвии и колбы.", "Enemies drop coins. Spend them in the shop on relics and flasks.", "敌人会掉落金币。在商店里用它们购买遗物和药瓶。", "Los enemigos sueltan monedas. Gástalas en la tienda en reliquias y frascos." } },
            { "hint.shrine", new[] { "Алтарь навсегда забирает одно сердце, но даёт реликвию.", "The shrine takes one heart forever, but gives a relic.", "祭坛会永久夺走一颗心，但给你一件遗物。", "El altar se lleva un corazón para siempre, pero da una reliquia." } },
            { "hint.elite", new[] { "Золотые враги — элита: крепче, но роняют больше монет.", "Golden enemies are elites: tougher, but they drop more coins.", "金色敌人是精英：更强壮，但掉落更多金币。", "Los enemigos dorados son élite: más duros, pero sueltan más monedas." } },
            { "hint.flask", new[] { "В каждом забеге колбы выглядят по-новому. Выпей, чтобы узнать, что внутри.", "Flasks look different every run. Drink one to learn what it does.", "每次冒险药瓶的样子都不同。喝下才知道效果。", "Los frascos cambian de aspecto en cada partida. Bebe para saber qué hacen." } },
            { "hint.floor", new[] { "Новый этаж: враги сильнее, а в конце ждёт босс.", "A new floor: enemies are stronger and a boss waits at the end.", "新的楼层：敌人更强，尽头有首领等待。", "Nuevo piso: los enemigos son más fuertes y al final espera un jefe." } },
            { "toast.bossDefeated", new[] { "{0} повержен!", "{0} is defeated!", "{0}被击败了！", "¡{0} ha caído!" } },
            { "pause.controls", new[] { "WASD — ход  ·  мышь — прицел  ·  ЛКМ — атака  ·  Shift / ПКМ — рывок  ·  Esc — пауза", "WASD — move  ·  mouse — aim  ·  LMB — attack  ·  Shift / RMB — dash  ·  Esc — pause", "WASD移动　鼠标瞄准　左键攻击　Shift或右键冲刺　Esc暂停", "WASD: moverse  ·  ratón: apuntar  ·  clic: atacar  ·  Shift / clic derecho: esquivar  ·  Esc: pausa" } },
            { "toast.konami", new[] { "Старая школа! +1 сердце и 30 монет", "Old school! +1 heart and 30 coins", "老派秘籍！+1颗心和30金币", "¡Vieja escuela! +1 corazón y 30 monedas" } },
            { "ctl.move", new[] { "ход", "move", "移动", "moverse" } },
            { "ctl.attack", new[] { "атака", "attack", "攻击", "atacar" } },
            { "ctl.dash", new[] { "рывок", "dash", "冲刺", "esquivar" } },
            { "ctl.pause", new[] { "пауза", "pause", "暂停", "pausa" } },
            { "room.secret.1", new[] { "Воспоминание: Работа", "A Memory: The Work", "回忆：工作", "Un recuerdo: El trabajo" } },
            { "room.secret.1.rule", new[] { "Здесь нет законов. Только то, что было до них", "There are no laws here. Only what came before them", "这里没有法则。只有法则之前的一切", "Aquí no hay leyes. Solo lo que hubo antes de ellas" } },
            { "hud.secretCard", new[] { "ТАЙНАЯ КОМНАТА", "SECRET ROOM", "秘密房间", "SALA SECRETA" } },
            { "obj.secret", new[] { "Осмотрись. Подходи к вещам со знаком !", "Look around. Walk up to things marked !", "四处看看。走近标有 ! 的东西", "Mira a tu alrededor. Acércate a lo que tenga !" } },
            { "toast.secret", new[] { "Стена рухнула — там проход!", "The wall crumbled — a passage!", "墙塌了——有条通道！", "¡El muro se derrumbó: hay un pasaje!" } },
            { "hint.secret", new[] { "Трещина в стене звучит пусто. Ударь по ней три раза.", "The cracked wall sounds hollow. Hit it three times.", "墙上的裂缝听起来是空的。打它三下。", "La grieta del muro suena hueca. Golpéala tres veces." } },
            { "hint.memory", new[] { "Это место не похоже на подземелье. Подходи к вещам — они помнят.", "This place is nothing like the dungeon. Walk up to things — they remember.", "这里一点也不像地牢。走近那些东西——它们还记得。", "Este lugar no se parece a la mazmorra. Acércate a las cosas: recuerdan." } },
            { "lore.board", new[] { "Доска", "Whiteboard", "黑板", "Pizarra" } },
            { "lore.board.text", new[] { "Правила, зачёркнутые десятки раз: «Лёд — убрать», «Неон — вернуть», «Тишина — ???». Внизу, обведено трижды: «Если правила не работают — поменяй правила».", "Rules crossed out dozens of times: \"Ice: cut\", \"Neon: bring back\", \"Silence: ???\". At the bottom, circled three times: \"If the rules don't work, change the rules.\"", "被划掉几十次的规则：“冰面：删掉”“霓虹：加回来”“寂静：？？？”。最下面圈了三遍：“规则不管用，就改规则。”", "Reglas tachadas decenas de veces: «Hielo: quitar», «Neón: volver a poner», «Silencio: ???». Abajo, rodeado tres veces: «Si las reglas no funcionan, cambia las reglas»." } },
            { "lore.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.photo.text", new[] { "Двое на берегу моря, оба смеются. На обороте: «Доделаю игру — и поедем снова». Дата выцвела.", "Two people on a beach, both laughing. On the back: \"Once the game is done, we'll go again.\" The date has faded.", "两个人在海边，都在笑。背面写着：“等游戏做完，我们再去一次。”日期已经褪色了。", "Dos personas en la playa, riendo. Al dorso: «Cuando termine el juego, volveremos». La fecha se ha borrado." } },
            { "lore.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.calendar.text", new[] { "Каждый день зачёркнут, месяц за месяцем. В последней клетке: «Релиз». Его зачёркивали и вписывали заново семь раз.", "Every day is crossed out, month after month. In the last square: \"Release\". It was crossed out and written again seven times.", "每一天都被划掉了，一个月又一个月。最后一格写着“发布”。它被划掉又重写了七次。", "Cada día está tachado, mes tras mes. En la última casilla: «Lanzamiento». Lo tacharon y lo volvieron a escribir siete veces." } },
            { "lore.computer", new[] { "Компьютер", "Computer", "电脑", "Ordenador" } },
            { "lore.computer.text", new[] { "На экране папка: «игра_финал», «игра_финал_2», «игра_финал_ТОЧНО», «игра_финал_ТОЧНО_v7». Последнее письмо так и не отправлено: «Прости, ещё чуть-чуть. Осталось только поправить правила».", "A folder on the screen: \"game_final\", \"game_final_2\", \"game_final_REALLY\", \"game_final_REALLY_v7\". The last email was never sent: \"Sorry, just a little longer. I only need to fix the rules.\"", "屏幕上有个文件夹：“游戏_最终版”“游戏_最终版2”“游戏_真最终版”“游戏_真最终版v7”。最后一封邮件始终没有发出：“对不起，再等一下。只剩规则要改了。”", "Una carpeta en pantalla: «juego_final», «juego_final_2», «juego_final_DE_VERDAD», «juego_final_DE_VERDAD_v7». El último correo nunca se envió: «Perdona, solo un poco más. Solo me falta arreglar las reglas»." } },
            { "lore.maker", new[] { "Создатель", "The Maker", "创造者", "El Creador" } },
            { "lore.maker.text", new[] { "«Я хотел сделать идеальную игру. Каждый раз казалось: ещё одно правило — и всё сложится. Потом я перестал выходить отсюда… а потом остался внутри насовсем. Если встретишь того, кто сидит на троне законов, скажи ему: игру уже можно выпускать».", "\"I wanted to make a perfect game. Every time it felt like one more rule would make it all fit. Then I stopped leaving this room… and then I stayed inside for good. If you meet the one on the throne of laws, tell him: the game is ready to ship.\"", "“我想做出一款完美的游戏。每次都觉得：再加一条规则，一切就对了。后来我不再走出这个房间……再后来，我干脆永远留在了里面。如果你见到法则王座上的那个人，告诉他：游戏已经可以发布了。”", "«Quería hacer un juego perfecto. Siempre parecía que con una regla más todo encajaría. Luego dejé de salir de esta habitación… y al final me quedé dentro para siempre. Si ves al que se sienta en el trono de las leyes, dile: el juego ya puede salir»." } },
            { "boss.line.1", new[] { "Это правило тоже не работает!", "This rule doesn't work either!", "这条规则也不管用！", "¡Esta regla tampoco funciona!" } },
            { "boss.line.2", new[] { "Ещё одна правка — и всё станет идеально.", "One more fix and it will be perfect.", "再改一次，就完美了。", "Un ajuste más y será perfecto." } },
            { "boss.line.3", new[] { "Почему ты всё ещё проходишь?!", "Why do you keep getting through?!", "你为什么还能过关？！", "¿¡Por qué sigues pasando!?" } },
            { "boss.line.4", new[] { "Я перепишу и тебя.", "I will rewrite you too.", "我连你也要重写。", "También te reescribiré a ti." } },
            { "boss.line.5", new[] { "Ещё не готово. Ещё не готово!", "It's not ready. It's not ready!", "还没好。还没好！", "Aún no está listo. ¡Aún no está listo!" } },
            { "boss.line.6", new[] { "Финальная версия. Точно финальная.", "Final version. Really final.", "最终版。真的是最终版。", "Versión final. Final de verdad." } },
            { "boss.enraged", new[] { "Хватит! Начну всё с нуля!", "Enough! I'll start over from scratch!", "够了！我要从头再来！", "¡Basta! ¡Empezaré desde cero!" } },
            { "boss.death", new[] { "…Может, она и правда уже готова.", "…Maybe it really is ready.", "……也许它真的已经完成了。", "…Quizá de verdad ya esté lista." } },
            { "room.secret.0", new[] { "Воспоминание: Мечта", "A Memory: The Dream", "回忆：梦想", "Un recuerdo: El sueño" } },
            { "room.secret.0.rule", new[] { "Здесь он ещё только мечтал о своей игре", "Here he was only dreaming of his game", "这时他还只是在梦想他的游戏", "Aquí aún solo soñaba con su juego" } },
            { "room.secret.2", new[] { "Воспоминание: Тишина", "A Memory: The Silence", "回忆：寂静", "Un recuerdo: El silencio" } },
            { "room.secret.2.rule", new[] { "Здесь уже никого нет. Только экран всё ещё светится", "Nobody is here anymore. Only the screen still glows", "这里已经没有人了。只有屏幕还亮着", "Ya no queda nadie. Solo la pantalla sigue encendida" } },
            { "lore.dream.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.dream.calendar.text", new[] { "Через полгода обведён день: «РЕЛИЗ!!!» Рядом нарисованы сердечко и море.", "A day six months ahead is circled: \"RELEASE!!!\" Next to it, a little heart and the sea.", "半年后的一天被圈了起来：“发布！！！”旁边画着一颗心和大海。", "Un día dentro de seis meses está marcado: «¡¡¡LANZAMIENTO!!!». Al lado, un corazoncito y el mar." } },
            { "lore.dream.tv", new[] { "Телевизор", "TV", "电视", "Televisor" } },
            { "lore.dream.tv.text", new[] { "В новостях: «Игра, которую сделал один человек, покорила мир». Он смотрит на экран, как на обещание.", "On the news: \"A game made by one person has conquered the world.\" He looks at the screen like it's a promise.", "新闻里说：“一个人做出的游戏征服了世界。”他看着屏幕，像看着一个承诺。", "En las noticias: «Un juego hecho por una sola persona conquista el mundo». Él mira la pantalla como si fuera una promesa." } },
            { "lore.dream.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.dream.photo.text", new[] { "Он и Лина у моря. Никакой игры ещё нет — и, кажется, никто по ней не скучает.", "He and Lina by the sea. There is no game yet, and nobody seems to miss it.", "他和莉娜在海边。那时还没有游戏，好像也没有人想念它。", "Él y Lina junto al mar. Todavía no hay ningún juego, y nadie parece echarlo de menos." } },
            { "lore.dream.desk", new[] { "Стол", "Desk", "书桌", "Escritorio" } },
            { "lore.dream.desk.text", new[] { "Чистый лист и одна строчка: «Игра, где каждая дверь — новый закон». Версия 0.1.", "A blank page and one line: \"A game where every door is a new law.\" Version 0.1.", "一张白纸，只有一行字：“每扇门都是新法则的游戏。”版本0.1。", "Una hoja en blanco y una línea: «Un juego donde cada puerta es una nueva ley». Versión 0.1." } },
            { "lore.dream.maker", new[] { "Создатель", "The Maker", "创造者", "El Creador" } },
            { "lore.dream.maker.text", new[] { "«Представь: каждая дверь меняет правила! Полгода — и выпущу. Ну, может, год. А потом сразу к морю, обещаю».", "\"Imagine: every door changes the rules! Six months and it's out. Well, maybe a year. And then straight to the sea, I promise.\"", "“想象一下：每扇门都会改变规则！半年就能发布。嗯，也许一年。然后我们马上去海边，我保证。”", "«Imagina: ¡cada puerta cambia las reglas! Seis meses y lo publico. Bueno, quizá un año. Y luego directos al mar, te lo prometo»." } },
            { "lore.dream.lina", new[] { "Лина", "Lina", "莉娜", "Lina" } },
            { "lore.dream.lina.text", new[] { "«Он светится, когда рассказывает про эту игру. Я уже купила билеты к морю — на после релиза. Пусть будет сюрприз».", "\"He lights up when he talks about this game. I've already bought tickets to the sea, for after the release. Let it be a surprise.\"", "“他一说起这个游戏就两眼发光。我已经买好了去海边的票，等发布以后用。就当是个惊喜吧。”", "«Se ilumina cuando habla de este juego. Ya compré billetes al mar, para después del lanzamiento. Que sea una sorpresa»." } },
            { "lore.silence.calendar", new[] { "Календарь", "Calendar", "日历", "Calendario" } },
            { "lore.silence.calendar.text", new[] { "Календарь остановился на одном дне. Дальше страницы пустые — их никто не переворачивал.", "The calendar stopped on one day. The pages after it are blank; nobody turned them.", "日历停在了某一天。后面的页都是空白的，没有人再翻过。", "El calendario se detuvo en un día. Las páginas siguientes están en blanco: nadie las pasó." } },
            { "lore.silence.photo", new[] { "Фото", "Photo", "照片", "Foto" } },
            { "lore.silence.photo.text", new[] { "Фото у моря лежит лицом вниз. На обороте: «Доделаю игру — и поедем снова». Слово «снова» зачёркнуто.", "The photo from the sea lies face down. On the back: \"Once the game is done, we'll go again.\" The word \"again\" is crossed out.", "海边的照片背面朝上放着。背面写着：“等游戏做完，我们再去一次。”“再”字被划掉了。", "La foto del mar está boca abajo. Al dorso: «Cuando termine el juego, volveremos». La palabra «volveremos» está tachada." } },
            { "lore.silence.bed", new[] { "Кровать", "Bed", "床", "Cama" } },
            { "lore.silence.bed.text", new[] { "Заправлена идеально ровно. На ней давно никто не спал.", "Made perfectly neat. Nobody has slept in it for a long time.", "床铺得整整齐齐。已经很久没人在上面睡过了。", "Hecha a la perfección. Hace mucho que nadie duerme en ella." } },
            { "lore.silence.boxes", new[] { "Коробки", "Boxes", "纸箱", "Cajas" } },
            { "lore.silence.boxes.text", new[] { "Подписаны маркером: «Вещи для нового дома». Скотч не тронут. Новый дом так и не дождался.", "Labelled in marker: \"Things for the new home\". The tape is untouched. The new home never got them.", "箱子上用记号笔写着：“搬去新家的东西”。胶带没有拆过。新家一直没有等到它们。", "Rotuladas con rotulador: «Cosas para la casa nueva». La cinta está intacta. La casa nueva nunca las recibió." } },
            { "lore.silence.fridge", new[] { "Холодильник", "Fridge", "冰箱", "Nevera" } },
            { "lore.silence.fridge.text", new[] { "Внутри пусто. На дверце записка его почерком: «Поем, когда закончу этот уровень». Ниже почерком Лины: «Ты обещал прийти на ужин».", "It is empty inside. A note on the door in his handwriting: \"I'll eat when this level is done.\" Below, in Lina's: \"You promised to come to dinner.\"", "里面空空的。门上贴着他写的便条：“做完这一关再吃。”下面是莉娜的字迹：“你答应过来吃晚饭的。”", "Está vacía. En la puerta, una nota con su letra: «Comeré cuando termine este nivel». Debajo, con la letra de Lina: «Prometiste venir a cenar»." } },
            { "lore.silence.computer", new[] { "Компьютер", "Computer", "电脑", "Ordenador" } },
            { "lore.silence.computer.text", new[] { "Экран светится в пустой комнате: «RULECRAWL — запущено 1461 день назад». В окне игры кто-то сидит на троне из правил и что-то переписывает.", "The screen glows in the empty room: \"RULECRAWL — running for 1461 days.\" In the game window someone sits on a throne of rules, rewriting something.", "屏幕在空荡荡的房间里亮着：“RULECRAWL——已运行1461天”。游戏窗口里，有人坐在由规则组成的王座上，不停地改写着什么。", "La pantalla brilla en la habitación vacía: «RULECRAWL: en ejecución desde hace 1461 días». En la ventana del juego, alguien se sienta en un trono de reglas y reescribe algo." } },
            { "lore.silence.lina", new[] { "Лина", "Lina", "莉娜", "Lina" } },
            { "lore.silence.lina.text", new[] { "«Я приходила каждый день. Он сидел здесь и разговаривал с кем-то внутри экрана. А однажды его просто… не стало. Только компьютер всё ещё работает. Если ты оттуда — скажи ему, что я жду».", "\"I came every day. He sat here, talking to someone inside the screen. And one day he was just… gone. Only the computer is still running. If you're from in there, tell him I'm waiting.\"", "“我每天都来。他坐在这里，和屏幕里的什么人说话。后来有一天，他就……不见了。只有电脑还在运行。如果你是从那里面来的，告诉他，我在等他。”", "«Venía cada día. Él se sentaba aquí y hablaba con alguien dentro de la pantalla. Y un día simplemente… desapareció. Solo el ordenador sigue encendido. Si vienes de ahí dentro, dile que lo estoy esperando»." } },
            { "lore.page", new[] { "Последняя страница", "The Last Page", "最后一页", "La última página" } },
            { "lore.page.text", new[] { "Почерк Создателя: «Мечта. Работа. Тишина. Если кто-то соберёт всё это — значит, я ещё могу вспомнить, кем был. Найди меня наверху. Я на троне законов».", "In the Maker's handwriting: \"The dream. The work. The silence. If someone gathers all of this, then I can still remember who I was. Find me at the top. I'm on the throne of laws.\"", "创造者的笔迹：“梦想。工作。寂静。如果有人把这些都收集起来，就说明我还能想起自己是谁。到最上面来找我。我在法则的王座上。”", "Con la letra del Creador: «El sueño. El trabajo. El silencio. Si alguien reúne todo esto, aún puedo recordar quién fui. Búscame arriba. Estoy en el trono de las leyes»." } },
            { "toast.allMemories", new[] { "Все воспоминания собраны! Открыта истинная концовка", "All memories gathered! The true ending is unlocked", "所有回忆都已收集！真结局已解锁", "¡Todos los recuerdos reunidos! Final verdadero desbloqueado" } },
            { "boss.mem.1", new[] { "Откуда ты знаешь про ту комнату?", "How do you know about that room?", "你怎么知道那个房间？", "¿Cómo sabes lo de esa habitación?" } },
            { "boss.mem.2", new[] { "Лина?.. Нет. Не отвлекай меня!", "Lina?.. No. Don't distract me!", "莉娜？……不。别让我分心！", "¿Lina?.. No. ¡No me distraigas!" } },
            { "boss.mem.3", new[] { "Я почти вспомнил… Нет! Правила важнее!", "I almost remember… No! The rules matter more!", "我差点想起来了……不！规则更重要！", "Casi lo recuerdo… ¡No! ¡Las reglas importan más!" } },
            { "ending.label", new[] { "КОНЦОВКА", "ENDING", "结局", "FINAL" } },
            { "end.ending", new[] { "Концовка: {0} ({1}/{2})", "Ending: {0} ({1}/{2})", "结局：{0}（{1}/{2}）", "Final: {0} ({1}/{2})" } },
            { "ending.0.name", new[] { "Ещё одна правка", "One More Fix", "再改一次", "Un ajuste más" } },
            { "ending.0.1", new[] { "Законодатель рассыпался на тысячи строк правил.", "The Lawgiver crumbled into a thousand lines of rules.", "立法者碎成了成千上万行规则。", "El Legislador se deshizo en mil líneas de reglas." } },
            { "ending.0.3", new[] { "Подземелье перестроилось, двери снова ждут. Может, в его стенах спрятано то, что он забыл?", "The dungeon rebuilt itself and the doors are waiting again. Maybe what he forgot is hidden in its walls?", "地牢重新排列，门又在等待了。也许他遗忘的东西就藏在墙里？", "La mazmorra se reconstruyó y las puertas esperan de nuevo. ¿Quizá lo que él olvidó se oculta en sus muros?" } },
            { "ending.1.name", new[] { "Отпусти", "Let It Go", "放手", "Déjalo ir" } },
            { "ending.1.1", new[] { "Ты передал ему слова из той комнаты: «Игру уже можно выпускать».", "You gave him the words from that room: \"The game is ready to ship.\"", "你把那个房间里的话带给了他：“游戏已经可以发布了。”", "Le diste las palabras de aquella habitación: «El juego ya puede salir»." } },
            { "ending.1.2", new[] { "Законодатель опустил перо. Впервые за много лет он ничего не исправил.", "The Lawgiver put down his pen. For the first time in years, he changed nothing.", "立法者放下了笔。多年来第一次，他什么也没有改。", "El Legislador dejó la pluma. Por primera vez en años, no cambió nada." } },
            { "ending.1.3", new[] { "Но он так и не вспомнил, кем был. Остальные воспоминания всё ещё где-то в стенах.", "But he still didn't remember who he was. The other memories are still somewhere in the walls.", "但他依然没有想起自己是谁。其余的回忆仍藏在墙里的某处。", "Pero aún no recordó quién era. Los demás recuerdos siguen en algún lugar de los muros." } },
            { "ending.2.name", new[] { "Версия 1.0", "Version 1.0", "1.0版", "Versión 1.0" } },
            { "ending.2.1", new[] { "Ты принёс ему всё, что он забыл: мечту, работу и тишину.", "You brought him everything he had forgotten: the dream, the work and the silence.", "你把他遗忘的一切都带给了他：梦想、工作和寂静。", "Le trajiste todo lo que había olvidado: el sueño, el trabajo y el silencio." } },
            { "ending.2.2", new[] { "Законодатель снял корону из правил. Под ней был просто уставший человек.", "The Lawgiver took off his crown of rules. Under it was just a tired man.", "立法者摘下了规则之冠。冠下只是一个疲惫的人。", "El Legislador se quitó la corona de reglas. Debajo solo había un hombre cansado." } },
            { "ending.2.3", new[] { "Он нажал «Опубликовать». Игра не была идеальной. Но она была готова.", "He pressed \"Publish\". The game wasn't perfect. But it was done.", "他按下了“发布”。游戏并不完美。但它完成了。", "Pulsó «Publicar». El juego no era perfecto. Pero estaba terminado." } },
            { "ending.2.4", new[] { "Потом он выключил компьютер и пошёл к морю. Лина ждала.", "Then he turned off the computer and went to the sea. Lina was waiting.", "然后他关掉了电脑，向大海走去。莉娜在等他。", "Luego apagó el ordenador y fue hacia el mar. Lina lo esperaba." } },
            { "ending.2.5", new[] { "Спасибо, что дошёл до конца.", "Thank you for reaching the end.", "感谢你走到最后。", "Gracias por llegar hasta el final." } },
            { "codex.story", new[] { "ИСТОРИЯ", "STORY", "故事", "HISTORIA" } },
            { "codex.memories", new[] { "Воспоминания: {0}/{1}", "Memories: {0}/{1}", "回忆：{0}/{1}", "Recuerdos: {0}/{1}" } },
            { "codex.endings", new[] { "Концовки: {0}/{1}", "Endings: {0}/{1}", "结局：{0}/{1}", "Finales: {0}/{1}" } },
            { "codex.watch", new[] { "СМОТРЕТЬ", "WATCH", "观看", "VER" } },
            { "codex.unknownMemory", new[] { "Ещё не найдено. Ищи трещины в стенах", "Not found yet. Look for cracks in the walls", "尚未找到。留意墙上的裂缝", "Aún no encontrado. Busca grietas en los muros" } },
            { "ending.0.how", new[] { "Победи Законодателя", "Defeat the Lawgiver", "击败立法者", "Derrota al Legislador" } },
            { "ending.1.how", new[] { "Победи, найдя воспоминание в том же забеге", "Win after finding a memory in the same run", "在同一次冒险中找到回忆后获胜", "Gana tras encontrar un recuerdo en la misma partida" } },
            { "ending.2.how", new[] { "Собери все три воспоминания и победи", "Gather all three memories and win", "收集全部三段回忆并获胜", "Reúne los tres recuerdos y gana" } },
            { "ending.0.2", new[] { "Но где-то глубоко внизу снова заскрипело перо…", "But deep below, a pen began to scratch again…", "但在很深的地下，羽毛笔又沙沙作响……", "Pero en lo más hondo, una pluma volvió a rasgar…" } },
            { "cs.skip", new[] { "Esc — пропустить", "Esc — skip", "Esc跳过", "Esc: saltar" } },
            { "cs.mem.0", new[] { "Тепло. Пахнет кофе и морем. Тогда всё только начиналось.", "Warmth. It smells of coffee and the sea. Back then, everything was just beginning.", "温暖。空气里有咖啡和大海的味道。那时一切才刚刚开始。", "Calidez. Huele a café y a mar. Entonces todo acababa de empezar." } },
            { "cs.mem.1", new[] { "Тикают часы. Гудит компьютер. Кто-то давно не спал.", "A clock ticks. A computer hums. Someone hasn't slept in a long time.", "时钟滴答作响。电脑嗡嗡运转。有人很久没睡了。", "Un reloj hace tictac. Un ordenador zumba. Alguien lleva mucho sin dormir." } },
            { "cs.mem.2", new[] { "Тишина. Только экран светится в темноте.", "Silence. Only a screen glows in the dark.", "寂静。只有屏幕在黑暗中亮着。", "Silencio. Solo una pantalla brilla en la oscuridad." } },
            { "cs.meet.1", new[] { "Ещё один. Ты тоже пришёл ломать мои правила?", "Another one. Have you come to break my rules too?", "又来一个。你也是来破坏我的规则的？", "Otro más. ¿Tú también vienes a romper mis reglas?" } },
            { "cs.meet.2", new[] { "Каждая дверь — моя правка. Каждый закон — шаг к идеальной игре.", "Every door is my fix. Every law is a step towards the perfect game.", "每一扇门都是我的修改。每一条法则都是通往完美游戏的一步。", "Cada puerta es un ajuste mío. Cada ley, un paso hacia el juego perfecto." } },
            { "cs.meet.mem", new[] { "Ты… пахнешь морем? Нет. Это неважно.", "You… smell of the sea? No. It doesn't matter.", "你……身上有大海的味道？不。这不重要。", "¿Hueles… a mar? No. No importa." } },
            { "cs.meet.all", new[] { "Ты был в моей комнате. Ты видел… Нет! Я ещё не закончил!", "You've been in my room. You saw… No! I'm not done yet!", "你去过我的房间。你看到了……不！我还没完成！", "Has estado en mi habitación. Has visto… ¡No! ¡Todavía no he terminado!" } },
            { "cs.meet.3", new[] { "Посмотрим, выдержишь ли ты все законы сразу!", "Let's see if you can stand every law at once!", "让我看看你能不能承受所有法则！", "¡Veamos si soportas todas las leyes a la vez!" } },
            { "cs.e0.1", new[] { "Ошибка… И эта версия неудачная…", "An error… This version failed too…", "错误……这个版本也失败了……", "Un error… Esta versión también falló…" } },
            { "cs.e0.2", new[] { "Версия 8. Финальная. Точно финальная.", "Version 8. Final. Really final.", "第8版。最终版。真的是最终版。", "Versión 8. Final. Final de verdad." } },
            { "cs.e1.1", new[] { "Зачем ты пришёл? Добить меня?", "Why are you here? To finish me off?", "你来做什么？来了结我吗？", "¿A qué has venido? ¿A rematarme?" } },
            { "cs.e1.2", new[] { "…Выпускать? Но она же не идеальна.", "…Ship it? But it isn't perfect.", "……发布？可它并不完美。", "…¿Publicarlo? Pero no es perfecto." } },
            { "cs.e1.3", new[] { "…Может, ей и не нужно быть идеальной.", "…Maybe it doesn't need to be perfect.", "……也许它并不需要完美。", "…Quizá no necesita ser perfecto." } },
            { "cs.e2.1", new[] { "Мечта… работа… тишина… Откуда у тебя всё это?", "The dream… the work… the silence… Where did you get all this?", "梦想……工作……寂静……你从哪里得到这些的？", "El sueño… el trabajo… el silencio… ¿De dónde has sacado todo esto?" } },
            { "cs.e2.2", new[] { "Я вспомнил. Меня ждут.", "I remember now. Someone is waiting for me.", "我想起来了。有人在等我。", "Ya lo recuerdo. Alguien me espera." } },
            { "cs.e2.3", new[] { "Ну что? К морю?", "So? To the sea?", "怎么样？去海边吗？", "¿Y bien? ¿Al mar?" } },
            { "cs.e2.4", new[] { "К морю. Я же обещал.", "To the sea. I promised.", "去海边。我答应过的。", "Al mar. Te lo prometí." } },
        };
    }
}
